CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_validacion_vistas` AS
select `v_valida_vista_rol`.`vista` AS `vista`,`v_valida_vista_rol`.`nmetrics_vista` AS `nmetrics`,sum(`v_valida_vista_rol`.`n_metricas_rol`) AS `metricas_con_rol`,round(((100 * sum(`v_valida_vista_rol`.`n_metricas_rol`)) / nullif(`v_valida_vista_rol`.`nmetrics_vista`,0)),0) AS `cobertura_pct`,count(0) AS `roles_distintos`,max(`v_valida_vista_rol`.`n_metricas_rol`) AS `metricas_dominante`,round(((100 * max(`v_valida_vista_rol`.`n_metricas_rol`)) / sum(`v_valida_vista_rol`.`n_metricas_rol`)),0) AS `pureza_pct`,substring_index((group_concat(`v_valida_vista_rol`.`role_id` order by `v_valida_vista_rol`.`n_metricas_rol` DESC separator '||') collate utf8_spanish_ci),'||',1) AS `rol_dominante`,(case when (((`v_valida_vista_rol`.`vista` collate utf8_spanish_ci) regexp 'SUMMARY|ALL ') or (count(0) >= 10)) then 'paraguas' when (((max(`v_valida_vista_rol`.`n_metricas_rol`) / sum(`v_valida_vista_rol`.`n_metricas_rol`)) >= 0.95) and (count(0) <= 2)) then 'concordante' when ((max(`v_valida_vista_rol`.`n_metricas_rol`) / sum(`v_valida_vista_rol`.`n_metricas_rol`)) >= 0.70) then 'mayoria_clara' else 'revisar' end) AS `clasificacion` from `v_valida_vista_rol` group by `v_valida_vista_rol`.`vista`,`v_valida_vista_rol`.`nmetrics_vista`;
